/* HEXA BATTLEGROUNDS setup — PART 70 OF 80. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-pattern-19', 'pattern', 'mission', 'Pattern Lock', 'logic', 2, array['office','helpdesk','learning','social','any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[3,4,6,7,5]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo is turned 90° CLOCKWISE (the top row of the photo is the left column of the lock)."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n7  8  9\n4  5  6\n1  2  3"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["25368"]}]'::jsonb, false, 3, 200, 'First turn Intel''s picture back the right way using Scout''s note, then read Decoder''s number for each dot in order.', 'true path 7-4-8-5-1 → 25368', null, 25, 'published'), ('airdrop-pattern-40', 'pattern', 'airdrop', 'Pattern Lock', 'logic', 1, array['any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[6,4,2,5]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo of the lock is the right way up."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n8  1  6\n7  9  4\n5  3  2"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["5964"]}]'::jsonb, false, 3, 150, 'First turn Intel''s picture back the right way using Scout''s note, then read Decoder''s number for each dot in order.', 'true path 6-4-2-5 → 5964', null, 25, 'published'), ('airdrop-pattern-41', 'pattern', 'airdrop', 'Pattern Lock', 'logic', 1, array['any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[6,3,4,0]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo of the lock was taken UPSIDE DOWN (turned 180°)."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n7  8  9\n4  5  6\n1  2  3"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["9653"]}]'::jsonb, false, 3, 150, 'First turn Intel''s picture back the right way using Scout''s note, then read Decoder''s number for each dot in order.', 'true path 2-5-4-8 → 9653', null, 25, 'published'), ('airdrop-pattern-42', 'pattern', 'airdrop', 'Pattern Lock', 'logic', 1, array['any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[6,7,4,1,5,2]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo is a MIRROR image (left and right swapped)."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n7  9  4\n1  8  3\n2  6  5"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["568917"]}]'::jsonb, false, 3, 150, 'First turn Intel''s picture back the right way using Scout''s note, then read Decoder''s number for each dot in order.', 'true path 8-7-4-1-3-0 → 568917', null, 25, 'published'), ('airdrop-pattern-43', 'pattern', 'airdrop', 'Pattern Lock', 'logic', 2, array['any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[5,2,4,3]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo is turned 90° CLOCKWISE (the top row of the photo is the left column of the lock)."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n7  8  9\n4  5  6\n1  2  3"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["8752"]}]'::jsonb, false, 3, 150, 'First turn Intel''s picture back the right way using Scout''s note, then read Decoder''s number for each dot in order.', 'true path 1-0-4-7 → 8752', null, 25, 'published'), ('mission-codebreak-0', 'codebreak', 'mission', 'Code Breaker', 'logic', 1, array['boardroom','access','testing','learning','any']::text[], 'Someone already tried to open this keypad. Intel has their tries and the keypad''s answers, Decoder knows what the lights mean, Scout found one fact about the code.', '{"intel":{"title":"Earlier tries","body":"3 6 2   →   —\n5 6 3   →   ○\n7 3 4   →   —\n6 4 5   →   ●","big":true},"decoder":{"title":"What the lights mean","body":"● = a right digit in the right place\n○ = a right digit in the wrong place\n— = no digit right\nThe code has 3 different digits from 1 to 8."},"scout":{"title":"What you found","body":"The LAST digit is bigger than the first."}}'::jsonb, '[{"label":"3-digit code","accept":["185"]}]'::jsonb, false, 3, 200, 'Start with the try that has no lights at all: those digits are out. Then use the ● tries to pin positions. Scout''s fact settles the last choice.', 'secret 185 (The LAST digit is bigger than the first.)', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-codebreak-1', 'codebreak', 'mission', 'Code Breaker', 'logic', 1, array['boardroom','access','testing','learning','any']::text[], 'Someone already tried to open this keypad. Intel has their tries and the keypad''s answers, Decoder knows what the lights mean, Scout found one fact about the code.', '{"intel":{"title":"Earlier tries","body":"6 2 1   →   ○\n1 3 6   →   ●\n2 4 3   →   —\n5 4 1   →   —","big":true},"decoder":{"title":"What the lights mean","body":"● = a right digit in the right place\n○ = a right digit in the wrong place\n— = no digit right\nThe code has 3 different digits from 1 to 8."},"scout":{"title":"What you found","body":"The FIRST digit is odd."}}'::jsonb, '[{"label":"3-digit code","accept":["786"]}]'::jsonb, false, 3, 200, 'Start with the try that has no lights at all: those digits are out. Then use the ● tries to pin positions. Scout''s fact settles the last choice.', 'secret 786 (The FIRST digit is odd.)', null, 25, 'published'), ('mission-codebreak-2', 'codebreak', 'mission', 'Code Breaker', 'logic', 1, array['boardroom','access','testing','lea